<style>.step{margin-bottom:20px}.panel-header{display:flex;justify-content:space-between}.types{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;padding:20px 22px}.types label{padding:14px;border:1px solid #e2d5ae;border-radius:10px}.step>label,.step>#table-field{display:block;margin:0 22px 18px}.delivery-fields{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:0 22px 18px}.delivery-fields[hidden]{display:none}.delivery-fields label{display:block}.delivery-fields input{display:block;width:100%;margin-top:6px;padding:10px;border:1px solid #d7c89e;border-radius:8px;background:#fffdf7}.delivery-fields span{font-weight:400;color:#6f6254}.step label>select,.step label>textarea,.step>label>textarea{display:block;width:100%;margin-top:6px;padding:10px;border:1px solid #d7c89e;border-radius:8px;background:#fffdf7}.tools{display:flex;gap:8px;padding:0 22px 18px}.tools input,.tools select{padding:10px;border:1px solid #d7c89e;border-radius:8px;background:#fffdf7}.tools input{flex:1}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;padding:0 22px 22px}.card{padding:15px;border:1px solid #e2d5ae;border-radius:12px;background:#fffdf7}.card[hidden]{display:none!important}.card.selected{border-color:#777;box-shadow:0 7px 20px rgba(0,0,0,.07)}.card h3{margin:5px 0}.card p{font-size:.8rem;color:#6f6254;min-height:32px}.bottom{display:flex;justify-content:space-between;align-items:center;gap:8px}.qty{display:flex;border:1px solid #d7c89e;border-radius:8px;overflow:hidden}.qty button{width:32px;border:0;background:#f6ecd0;font-size:18px}.qty input{width:38px;border:0;text-align:center;background:#fff}.options{margin-top:12px;padding:10px;background:#f7f7f5;border-radius:8px}.options[hidden],.note[hidden]{display:none}.options label{font-size:.72rem;font-weight:750}.note{margin-top:10px}.note textarea{width:100%;min-height:50px;border:1px solid #d7c89e;border-radius:8px;padding:7px}.summary{margin:0 22px 20px;padding:14px;background:#f8e7ae;border-radius:10px}.summary-line{display:flex;justify-content:space-between;padding:5px 0;gap:12px}.summary-line small{display:block;color:#6f6254}.summary-fee{border-top:1px dashed #cbbd95;margin-top:8px;padding-top:8px}.form-actions{margin:0 22px}.form-actions .button{margin-right:6px}@media(max-width:900px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.grid,.types{grid-template-columns:1fr}.tools{flex-direction:column}.form-actions{display:grid;grid-template-columns:1fr 1.3fr}.form-actions .button{margin:0}}
</style>
<script>
const form=document.getElementById('manual-order-form'),submit=document.getElementById('submit'),summary=document.getElementById('summary'),search=document.getElementById('product-search'),filter=document.getElementById('category-filter'),tableField=document.getElementById('table-field');
const comboBeverages=@json($comboBeverages);
const money=v=>'$'+Number(v).toLocaleString('es-CO',{maximumFractionDigits:0});
function applyProductFilters(){const q=search.value.trim().toLowerCase(),category=filter.value;let visibleCount=0;document.querySelectorAll('#product-grid .card').forEach(card=>{const name=card.dataset.name||'',categoryId=String(card.dataset.category||''),categoryName=card.querySelector('.eyebrow')?.textContent?.toLowerCase()||'',matchesSearch=!q||name.includes(q)||categoryName.includes(q),matchesCategory=!category||categoryId===String(category);const visible=matchesSearch&&matchesCategory;card.hidden=!visible;if(visible)visibleCount++;});document.getElementById('products-empty').hidden=visibleCount>0;}
search.addEventListener('input',applyProductFilters);filter.addEventListener('change',applyProductFilters);
function refresh(){let total=0,units=0,packaging=0,lines=[];const takeaway=document.querySelector('input[name="type"][value="PARA_LLEVAR"]')?.checked;const delivery=document.querySelector('input[name="type"][value="DOMICILIO"]')?.checked;const deliveryFee=Number(document.getElementById('delivery-fee')?.value||0)||0;document.querySelectorAll('.card').forEach(c=>{const i=c.querySelector('input[data-id]'),q=Number(i.value)||0;c.classList.toggle('selected',q>0);const n=c.querySelector('.note'),o=c.querySelector('.beverage'),comboChoice=c.querySelector('.combo-choice'),comboExtra=c.querySelector('.combo-extra');if(n)n.hidden=q===0;if(o)o.hidden=q===0;if(comboChoice){const comboOn=comboChoice.value==='SI';if(comboExtra)comboExtra.hidden=q===0||!comboOn;}if(q){let price=Number(i.dataset.price),detail='';if(i.dataset.juice==='1'){const prep=c.querySelector('[name^="juice_preparation"]')?.value||'AGUA';price=prep==='LECHE'?9500:8500;const f=c.querySelector('[name^="juice_fruit"]')?.selectedOptions[0]?.text||'';detail=(prep==='LECHE'?'En leche':'En agua')+' · '+f}else if(comboChoice?.value==='SI'){const type=c.querySelector('[data-combo-type]')?.selectedOptions[0]?.text||'';const flavor=c.querySelector('[data-combo-flavor]')?.value||'';price+=10000;detail=`COMBO +$10.000 · Papas a la francesa · ${type} · ${flavor}`;}else{const s=c.querySelector('.beverage select');detail=s?.value||''}const line=q*price;const fee=(takeaway||delivery)&&c.dataset.packaging==='1'?1500*q:0;total+=line;packaging+=fee;units+=q;lines.push(`<div class="summary-line"><span>${q} × ${i.closest('.card').querySelector('h3').textContent}<small>${detail}</small></span><strong>${money(line)}</strong></div>`)}});document.getElementById('items-count').textContent=`${units} producto${units===1?'':'s'} seleccionado${units===1?'':'s'}`;const feeLine=(takeaway||delivery)&&packaging?`<div class="summary-line summary-fee"><span>Empaques para llevar</span><strong>${money(packaging)}</strong></div>`:'';summary.innerHTML=lines.length?lines.join('')+feeLine+`<div class="summary-line"><strong>Total</strong><strong>${money(total+packaging+(delivery?deliveryFee:0))}</strong></div>`:'Agrega productos para ver el resumen.';submit.disabled=units===0;}
document.querySelectorAll('[data-plus]').forEach(b=>b.onclick=()=>{const i=document.querySelector(`input[data-id="${b.dataset.plus}"]`);i.value=Math.min(99,Number(i.value)+1);refresh()});document.querySelectorAll('[data-minus]').forEach(b=>b.onclick=()=>{const i=document.querySelector(`input[data-id="${b.dataset.minus}"]`);i.value=Math.max(0,Number(i.value)-1);refresh()});document.querySelectorAll('.beverage select,.juice select,.combo-choice,[data-combo-type],[data-combo-flavor]').forEach(s=>s.addEventListener('change',()=>{if(s.matches('.combo-choice')){const id=s.dataset.id,extra=document.querySelector(`[data-combo-extra="${id}"]`);if(extra)extra.hidden=s.value!=='SI';}if(s.matches('[data-combo-type]')){const id=s.getAttribute('data-combo-type'),flavor=document.querySelector(`[data-combo-flavor="${id}"]`),flavors=comboBeverages[s.value]?.flavors||[];if(flavor)flavor.innerHTML=flavors.map(value=>`<option value="${value}">${value}</option>`).join('');}refresh();}));document.querySelectorAll('.card .note textarea').forEach(t=>t.addEventListener('input',refresh));document.querySelectorAll('input[name="type"]').forEach(r=>r.addEventListener('change',()=>{const isTable=r.value==='MESA'&&r.checked;const isDelivery=r.value==='DOMICILIO'&&r.checked;tableField.style.display=isTable?'block':'none';document.getElementById('delivery-fields').hidden=!isDelivery;refresh()}));document.getElementById('delivery-fee').addEventListener('input',e=>{e.target.value=e.target.value.replace(/\D/g,'');refresh()});const initialType=document.querySelector('input[name="type"]:checked')?.value;tableField.style.display=initialType==='MESA'?'block':'none';document.getElementById('delivery-fields').hidden=initialType!=='DOMICILIO';refresh();applyProductFilters();
</script>
